const cfg = $('Loop Each Keyword+Location').first().json;
let terms;
try {
  const raw = $input.first().json.choices[0].message.content;
  terms = JSON.parse(raw);
} catch (e) {
  terms = [cfg.keyword];
}
const exclude = (cfg.exclude || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
return [{
  json: {
    keyword: cfg.keyword,
    location: cfg.location,
    expandedTerms: terms.map(t => String(t).toLowerCase()),
    excludeTerms: exclude
  }
}];

const ctx = $('Parse Expanded Terms').first().json;
const terms = ctx.expandedTerms.concat([ctx.keyword.toLowerCase()]);
const exclude = ctx.excludeTerms || [];
const location = (ctx.location || '').toLowerCase();

const freshTerms = ['fresher','entry level','entry-level','graduate','junior','0-1 year','0-2 years','trainee','new grad'];
const seniorExclude = ['senior','staff','principal',' lead ','5+ years','7+ years','10+ years'];

let arb = [];
try { arb = $('Fetch Arbeitnow Jobs').first().json.data || []; } catch(e) {}
let rok = [];
try {
  const rokRaw = $('Fetch RemoteOK Jobs').first().json;
  rok = Array.isArray(rokRaw) ? rokRaw.slice(1) : [];
} catch(e) {}
let adz = [];
try { adz = $('Fetch Adzuna Jobs').first().json.results || []; } catch(e) {}

const normalized = [];

for (const j of arb) {
  normalized.push({ id: 'arbeitnow-' + j.slug, title: j.title, company: j.company_name, location: j.location || (j.remote ? 'Remote' : ''), url: j.url, text: (j.title + ' ' + (j.description || '')).toLowerCase() });
}
for (const j of rok) {
  if (!j || !j.position) continue;
  normalized.push({ id: 'remoteok-' + (j.id || j.slug), title: j.position, company: j.company, location: j.location || 'Remote', url: j.url || ('https://remoteok.com/remote-jobs/' + j.id), text: (j.position + ' ' + (j.description || '') + ' ' + (j.tags || []).join(' ')).toLowerCase() });
}
for (const j of adz) {
  normalized.push({ id: 'adzuna-' + j.id, title: j.title, company: (j.company && j.company.display_name) || '', location: (j.location && j.location.display_name) || '', url: j.redirect_url, text: (j.title + ' ' + (j.description || '')).toLowerCase() });
}

const matched = normalized.filter(j => {
  const matchesKeyword = terms.some(t => j.text.includes(t));
  const hasExcluded = exclude.some(t => t && j.text.includes(t));
  const matchesLocation = !location || location === 'remote' ? true : (j.location || '').toLowerCase().includes(location) || j.text.includes('remote');
  const isSenior = seniorExclude.some(t => j.text.includes(t));
  return matchesKeyword && !hasExcluded && matchesLocation && !isSenior;
});

// cap candidates sent to the LLM classifier to control cost/tokens
const capped = matched.slice(0, 25);

return capped.map(j => ({ json: { ...j, searchKeyword: ctx.keyword, searchLocation: ctx.location } }));

const candidates = $input.all().map(i => i.json);
const compact = candidates.map(c => ({ id: c.id, title: c.title, company: c.company, snippet: (c.text || '').slice(0, 300) }));
return [{ json: { candidatesJson: JSON.stringify(compact), count: compact.length } }];

let decisions = [];
try {
  const raw = $input.first().json.choices[0].message.content;
  const cleaned = raw.replace(/```json|```/g, '').trim();
  decisions = JSON.parse(cleaned);
} catch (e) {
  decisions = [];
}
const decisionMap = new Map(decisions.map(d => [d.id, d]));
const candidates = $('Merge + Coarse Filter').all().map(i => i.json);
const kept = candidates.filter(c => {
  const d = decisionMap.get(c.id);
  return d && d.relevant === true && d.fresherFriendly === true;
});
return kept.map(c => ({ json: c }));
